header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex, nofollow');
$route=trim(substr($path,7),'/');$parts=explode('/',$route);$section=$parts[0]?:'overview';
$navigation=['overview'=>['◈','Overview'],'orders'=>['▤','My orders'],'wallet'=>['◉','Wallet'],'saved'=>['♡','Saved meals'],'bookings'=>['⌑','My occasions'],'returns'=>['↺','Returns & help'],'addresses'=>['⌂','Address book'],'settings'=>['⚙','Account settings'],'chat'=>['◌','Live concierge']];
