function customer_form(string $action):void{?><form method="post" action="/account/action/<?=esc($action)?>"><?=token()?><?php }
function customer_status(string $status):void{?><span class="c-status status-<?=esc($status)?>"><?=esc(ucwords(str_replace('_',' ',$status)))?></span><?php }
function customer_money_minor(int $value):string{return money($value/100);}
function customer_password(string $name,string $label,bool $new=false):void{?><label for="<?=esc($name)?>"><?=esc($label)?></label><input id="<?=esc($name)?>" name="<?=esc($name)?>" type="password" autocomplete="<?=$new?'new-password':'current-password'?>" autocapitalize="off" spellcheck="false" required <?=$new?'minlength="10" maxlength="72"':''?>><label class="auth-password-toggle" hidden><input type="checkbox" data-password-toggle aria-controls="<?=esc($name)?>"><span>Show password</span></label><?php }
function customer_order_card(array $order):void{?><article class="c-order"><div class="c-order-icon" aria-hidden="true">🍽</div><a href="/account/orders/<?=(int)$order['id']?>"><strong><?=esc($order['reference'])?></strong><small><?=esc(date('d M Y',strtotime($order['created_at'])))?> · <?=esc(ucfirst($order['fulfillment']))?></small></a><div class="c-order-value"><strong><?=money($order['total'])?></strong><?php customer_status($order['status']);?></div><a class="c-icon-link" href="/account/orders/<?=(int)$order['id']?>" aria-label="Open order <?=esc($order['reference'])?>">↗</a></article><?php }
function customer_meal_card(array $product,bool $saved=false):void{?><article class="c-meal"><a href="/product/<?=(int)$product['id']?>"><img src="<?=esc($product['image'])?>" alt="<?=esc($product['name'])?>" loading="lazy"></a><div><h3><a href="/product/<?=(int)$product['id']?>"><?=esc($product['name'])?></a></h3><p><?=money($product['price'])?></p><?php customer_form('favourite');?><input type="hidden" name="product_id" value="<?=(int)$product['id']?>"><input type="hidden" name="save" value="<?=$saved?'0':'1'?>"><button class="c-text-button"><?=$saved?'♥ Remove from saved':'♡ Save this dish'?></button></form></div></article><?php }
function customer_overview(array $u):void{
 $id=(int)$u['id'];$stats=one("SELECT COUNT(*) total,SUM(status NOT IN ('completed','cancelled')) active,COALESCE(SUM(CASE WHEN payment_status='paid' AND NOT EXISTS(SELECT 1 FROM payments p JOIN payment_gateway_context c ON c.payment_id=p.id WHERE p.entity_type='order' AND p.entity_id=orders.id AND p.status='success' AND c.mode='test') THEN total ELSE 0 END),0) spent,SUM(fulfillment='delivery') deliveries,SUM(fulfillment='pickup') pickups FROM orders WHERE user_id=?",[$id]);$mode=paystack_mode();$balance=wallet_balance($id,$mode);$orders=all('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 3',[$id]);$saved=(int)one('SELECT COUNT(*) n FROM customer_favourites WHERE user_id=?',[$id])['n'];$monthly=all("SELECT DATE_FORMAT(created_at,'%Y-%m') month,SUM(total) amount FROM orders WHERE user_id=? AND payment_status='paid' AND NOT EXISTS(SELECT 1 FROM payments p JOIN payment_gateway_context c ON c.payment_id=p.id WHERE p.entity_type='order' AND p.entity_id=orders.id AND p.status='success' AND c.mode='test') AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY month",[$id]);$amounts=array_column($monthly,'amount','month');$bars=[];for($i=5;$i>=0;$i--){$date=new DateTimeImmutable('first day of -'.$i.' month');$bars[]=['label'=>$date->format('M'),'amount'=>(float)($amounts[$date->format('Y-m')]??0)];}$maximum=max(1,...array_column($bars,'amount'));
 ?><section class="c-welcome"><div><span class="c-eyebrow">A TABLE WITH YOUR NAME ON IT</span><h2>Good food.<br><em>Your own rhythm.</em></h2><p>Welcome back, <?=esc(explode(' ',$u['name'])[0])?>. A little more flavour, a little less planning.</p><a class="c-button gold" href="/menu">Find your next favourite ↗</a></div><img src="/public/assets/banners/private-chef.webp" alt="A thoughtfully prepared dining experience"></section>
 <div class="c-metrics"><a class="c-card" href="/account/wallet"><small><?=$mode==='test'?'Test wallet':'Wallet balance'?></small><strong><?=customer_money_minor($balance)?></strong><span>Top up or see activity ↗</span></a><a class="c-card" href="/account/orders"><small>Orders in progress</small><strong><?=(int)$stats['active']?></strong><span>See what is cooking ↗</span></a><a class="c-card" href="/account/saved"><small>Saved favourites</small><strong><?=$saved?></strong><span>A menu that knows you ↗</span></a><div class="c-card"><small>Live dining spend</small><strong><?=money($stats['spent'])?></strong><span>Across your dining history</span></div></div>
 <div class="c-two-column"><section class="c-panel"><div class="c-section-title"><div><span class="c-eyebrow">YOUR DINING JOURNEY</span><h2>Six months of flavour.</h2></div><span class="c-chip">Paid orders</span></div><div class="c-bar-chart" role="img" aria-label="Paid order value by month"><?php foreach($bars as $bar):?><div><span class="c-bar-value"><?=money($bar['amount'])?></span><i style="height:<?=max(3,(int)round($bar['amount']/$maximum*115))?>px" title="<?=esc($bar['label'].': '.money($bar['amount']))?>"></i><small><?=$bar['label']?></small></div><?php endforeach;?></div><p class="c-muted c-small">Live paid order totals. Test payments and wallet top-ups are excluded.</p></section><section class="c-panel"><span class="c-eyebrow">HOW YOU DINE</span><h2>Your table, your way.</h2><?php $total=(int)$stats['total'];$percent=$total?round((int)$stats['deliveries']/$total*100):0;?><div class="c-donut-wrap"><div class="c-donut <?=$total?'':'empty'?>" style="--share:<?=$percent?>%" role="img" aria-label="<?=(int)$stats['deliveries']?> delivery and <?=(int)$stats['pickups']?> pickup orders"><div><strong><?=$total?></strong><small>orders</small></div></div><ul class="c-chart-legend"><li><i></i>Delivery <strong><?=(int)$stats['deliveries']?></strong></li><li><i></i>Pickup <strong><?=(int)$stats['pickups']?></strong></li></ul></div><?php if(!$total):?><p class="c-muted c-small">Your first order starts the story.</p><?php endif;?></section></div>
 <div class="c-two-column"><section class="c-panel"><div class="c-section-title"><h2>Recently at your table</h2><a href="/account/orders">All orders ↗</a></div><?php foreach($orders as $order)customer_order_card($order);if(!$orders):?><div class="c-empty"><span>🍽</span><h3>Something delicious is waiting.</h3><p>Your orders and progress will appear here.</p><a class="c-button" href="/menu">Explore the menu</a></div><?php endif;?></section><section class="c-panel c-host-note"><span class="c-eyebrow">A LITTLE OCCASION</span><h2>Stay present.<br><em>We’ll do the cooking.</em></h2><p>Bring a private chef into your space, or let us cater for your favourite people.</p><a class="c-button" href="/private-chef">Plan private dining ↗</a><a class="c-text-button" href="/account/chat">Talk to the concierge →</a></section></div>
 <section><div class="c-section-title"><div><span class="c-eyebrow">FROM OUR KITCHEN</span><h2>A few good reasons to return.</h2></div><a href="/menu">Full menu ↗</a></div><div class="c-meal-grid"><?php foreach(all('SELECT * FROM products WHERE available=1 ORDER BY featured DESC,id DESC LIMIT 4') as $product)customer_meal_card($product,(bool)one('SELECT product_id FROM customer_favourites WHERE user_id=? AND product_id=?',[$id,$product['id']]));?></div></section><?php
}
function customer_orders(array $u):void{
 $page=max(1,min(1000,(int)($_GET['page']??1)));$q=mb_substr(trim((string)($_GET['q']??'')),0,60);$params=[$u['id']];$filter='user_id=?';if($q!==''){$filter.=' AND (reference LIKE ? OR status LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}$count=(int)one('SELECT COUNT(*) n FROM orders WHERE '.$filter,$params)['n'];$orders=all('SELECT * FROM orders WHERE '.$filter.' ORDER BY id DESC LIMIT 15 OFFSET '.(($page-1)*15),$params);
 ?><section class="c-panel"><form class="c-search" method="get"><label class="sr-only" for="order-search">Search orders</label><input id="order-search" name="q" value="<?=esc($q)?>" placeholder="Search by reference or status"><button class="c-button">Find order</button></form><?php foreach($orders as $order)customer_order_card($order);if(!$orders):?><div class="c-empty"><h2>No orders here yet.</h2><a class="c-button gold" href="/menu">Discover the menu</a></div><?php endif;?><nav class="c-pagination" aria-label="Order pages"><?php if($page>1):?><a href="?page=<?=$page-1?>&q=<?=rawurlencode($q)?>">← Previous</a><?php endif;?><?php if($count>$page*15):?><a href="?page=<?=$page+1?>&q=<?=rawurlencode($q)?>">Next →</a><?php endif;?></nav></section><?php
}
function customer_detail(array $u,string $kind,int $id):void{
 $record=one('SELECT * FROM '.($kind==='order'?'orders':'bookings').' WHERE id=? AND user_id=?',[$id,$u['id']]);if(!$record){?><section class="c-panel"><h2>This request could not be found.</h2><a href="/account/orders">Back to your orders</a></section><?php return;}
 ?><section class="c-panel"><div class="c-section-title"><div><span class="c-eyebrow"><?=esc($record['reference'])?></span><h2><?=$kind==='order'?'Your order, in detail.':'Your occasion, thoughtfully planned.'?></h2></div><?php customer_status($record['status']);?></div><?php if(one("SELECT p.id FROM payments p JOIN payment_gateway_context c ON c.payment_id=p.id WHERE p.entity_type=? AND p.entity_id=? AND p.status='success' AND c.mode='test' LIMIT 1",[$kind,$id])):?><p class="c-notice">Test payment recorded — no real money was collected.</p><?php endif;?><div class="c-detail-facts"><span>Payment<strong><?=esc(ucfirst($record['payment_status']))?></strong></span><span><?=$kind==='order'?'Order total':'Quotation'?><strong><?=money($kind==='order'?$record['total']:($record['quote']??0))?></strong></span><span><?=$kind==='order'?'Fulfilment':'Event date'?><strong><?=esc($kind==='order'?ucfirst($record['fulfillment']):$record['event_date'])?></strong></span></div>
 <?php if($kind==='order'):?><ol class="c-order-timeline"><?php foreach(all('SELECT status,created_at FROM order_status_events WHERE order_id=? ORDER BY id',[$id]) as $event):?><li><strong><?=esc(ucfirst($event['status']))?></strong><small><?=esc(date('d M, H:i',strtotime($event['created_at'])))?></small></li><?php endforeach;?></ol><?php foreach(all('SELECT * FROM order_items WHERE order_id=?',[$id]) as $item):?><div class="c-line-item"><div><strong><?=esc($item['product_name'])?> × <?=(int)$item['quantity']?></strong><?php foreach(json_decode($item['customizations']??'[]',true)?:[] as $option):?><small><?=esc((string)$option)?></small><?php endforeach;?></div><b><?=money((float)$item['unit_price']*(int)$item['quantity'])?></b></div><?php endforeach;?><p class="c-muted">Delivery fee: <?=money($record['delivery_fee'])?></p><div class="c-address-block"><strong><?=esc($record['customer_name'])?></strong><p><?=nl2br(esc($record['address']?:'Pickup at the restaurant'))?></p><p><?=esc($record['notes']??'')?></p></div>
 <?php /* The existing reorder endpoint remains authoritative. */?><form method="post" action="/account/reorder"><?=token()?><input type="hidden" name="order_id" value="<?=$id?>"><button class="c-button">Order these favourites again ↻</button></form>
 <?php if($record['status']==='pending'&&$record['payment_status']==='unpaid'):?><details class="c-disclosure"><summary>Update delivery details or notes</summary><p class="c-muted c-small">Available before preparation/payment. To change items or a paid order, message the team.</p><?php customer_form('order/update');?><input type="hidden" name="order_id" value="<?=$id?>"><label for="order-address">Address</label><textarea id="order-address" name="address" rows="2"><?=esc($record['address'])?></textarea><label for="order-notes">Kitchen / delivery notes</label><textarea id="order-notes" name="notes" rows="2" maxlength="500"><?=esc($record['notes']??'')?></textarea><button class="c-button">Save order details</button></form></details><?php if(!one("SELECT id FROM payments WHERE entity_type='order' AND entity_id=? AND status='initialized'",[$id])):?><?php customer_form('order/cancel');?><input name="order_id" type="hidden" value="<?=$id?>"><button class="c-text-button danger">Cancel unpaid order</button></form><?php endif;endif;?>
 <?php else:?><div class="c-detail-facts"><span>Guests<strong><?=(int)$record['guests']?></strong></span><span>Deposit requested<strong><?=money($record['deposit'])?></strong></span><span>Time<strong><?=esc($record['event_time'])?></strong></span></div><p><?=nl2br(esc($record['location']))?></p><p><?=nl2br(esc($record['details']??''))?></p><?php endif;?>
 <?php if(paystack_can_pay($kind,$record)):?><div class="c-payment-options"><form method="post" action="/pay"><?=token()?><input name="type" type="hidden" value="<?=$kind?>"><input name="id" type="hidden" value="<?=$id?>"><button class="c-button gold" <?=paystack_enabled()?'':'disabled'?>>Continue with Paystack ↗</button></form><?php if(!one("SELECT id FROM payments WHERE entity_type=? AND entity_id=? AND status='initialized'",[$kind,$id])):?><?php customer_form('wallet/pay');?><input name="kind" type="hidden" value="<?=$kind?>"><input name="id" type="hidden" value="<?=$id?>"><button class="c-button">Pay from wallet</button></form><?php endif;?></div><?php endif;?><div class="c-inline-links"><a href="/account/chat">Ask the concierge →</a><a href="/account/returns">Report an issue / request a refund →</a></div></section><?php
}
function customer_wallet(array $u):void{
 $ledgerPage=max(1,min(100000,(int)($_GET['ledger_page']??1)));$topupPage=max(1,min(100000,(int)($_GET['topup_page']??1)));$mode=paystack_mode();$ledgerCount=(int)one('SELECT COUNT(*) n FROM wallet_ledger WHERE user_id=? AND mode=?',[$u['id'],$mode])['n'];$topupCount=(int)one('SELECT COUNT(*) n FROM wallet_topups WHERE user_id=?',[$u['id']])['n'];$live=wallet_balance((int)$u['id'],'live');$test=wallet_balance((int)$u['id'],'test');$nonce=$_SESSION['wallet_topup_nonce']??=bin2hex(random_bytes(24));$pending=one('SELECT * FROM wallet_topups WHERE nonce=? AND user_id=?',[$nonce,$u['id']]);if($pending&&$pending['status']==='success'){$nonce=$_SESSION['wallet_topup_nonce']=bin2hex(random_bytes(24));$pending=null;}
 ?><section class="c-wallet-card"><div><span class="c-eyebrow">YOUR DINING RESERVE</span><h2><?=customer_money_minor($mode==='live'?$live:$test)?></h2><p><?=$mode==='live'?'Live wallet balance':'Test wallet · simulated funds only'?></p></div><span class="c-wallet-seal">36°</span><small>Secure top-ups · instant wallet checkout · full activity history</small></section><?php if($mode==='test'):?><p class="c-notice">Test payments are enabled. Your real balance is <?=customer_money_minor($live)?> and remains separate. Test funds cannot be spent in live mode.</p><?php endif;?>
 <div class="c-two-column"><section class="c-panel"><h2>A little more in reserve.</h2><p class="c-muted">Top up securely through Paystack. Your balance updates after server-side verification.</p><?php customer_form('wallet/topup');?><input type="hidden" name="nonce" value="<?=esc($nonce)?>"><input name="mode" type="hidden" value="<?=$mode?>"><label for="topup-amount">Amount (₦)</label><input id="topup-amount" name="amount" type="number" min="500" max="500000" step="0.01" value="<?=$pending?number_format((int)$pending['amount']/100,2,'.',''):'5000'?>" required inputmode="decimal"><button class="c-button gold" <?=paystack_enabled()?'':'disabled'?>>Continue to Paystack ↗</button></form><?php if(!paystack_enabled()):?><p class="c-muted c-small">Top-ups are currently paused by the restaurant.</p><?php endif;?><?php if($pending):?><?php customer_form('wallet/new');?><button class="c-text-button">Start a different top-up</button></form><?php endif;?><p class="c-muted c-small">Wallet funds pay for meals and dining requests. Approved wallet refunds return to the original wallet; there is no cash-withdrawal feature.</p></section><section class="c-panel"><h2>Recent top-ups</h2><p class="c-muted c-small" data-wallet-refresh data-mode="<?=$mode?>" data-balance="<?=wallet_balance((int)$u['id'],$mode)?>" aria-live="polite">Pending payments are checked automatically while this page is open. You can also check a payment below.</p><?php $topups=all('SELECT reference,amount,mode,status FROM wallet_topups WHERE user_id=? ORDER BY id DESC LIMIT 6 OFFSET '.(($topupPage-1)*6),[$u['id']]);foreach($topups as $topup):?><div class="c-topup-row"><div><strong><?=customer_money_minor((int)$topup['amount'])?></strong><small><?=esc($topup['reference'])?> · <?=esc($topup['mode'])?></small><?php customer_status($topup['status']);?></div><?php if($topup['status']!=='success'):?><?php customer_form('wallet/verify');?><input name="reference" type="hidden" value="<?=esc($topup['reference'])?>"><button class="c-button small">Check status</button></form><?php endif;?></div><?php endforeach;if(!$topups):?><p class="c-muted">Your first top-up will appear here.</p><?php endif;?><nav class="c-pagination" aria-label="Top-up pages"><?php if($topupPage>1):?><a href="?topup_page=<?=$topupPage-1?>&ledger_page=<?=$ledgerPage?>">← Newer</a><?php endif;if($topupCount>$topupPage*6):?><a href="?topup_page=<?=$topupPage+1?>&ledger_page=<?=$ledgerPage?>">Earlier →</a><?php endif;?></nav></section></div>
 <section class="c-panel"><h2>Every movement, accounted for.</h2><div class="c-table-wrap"><table><thead><tr><th>Activity</th><th>Reference</th><th>Amount</th><th>Balance after</th><th>Date</th></tr></thead><tbody><?php foreach(all('SELECT * FROM wallet_ledger WHERE user_id=? AND mode=? ORDER BY id DESC LIMIT 50 OFFSET '.(($ledgerPage-1)*50),[$u['id'],$mode]) as $line):?><tr><td><?=esc(ucfirst($line['kind']))?></td><td><?=esc($line['reference'])?></td><td class="<?=(int)$line['amount']>=0?'positive':'negative'?>"><?=(int)$line['amount']>=0?'+':''?><?=customer_money_minor((int)$line['amount'])?></td><td><?=customer_money_minor((int)$line['balance_after'])?></td><td><?=esc(date('d M, H:i',strtotime($line['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><p class="c-muted c-small">Page <?=$ledgerPage?> · <?=$mode?> wallet.</p><nav class="c-pagination" aria-label="Wallet activity pages"><?php if($ledgerPage>1):?><a href="?ledger_page=<?=$ledgerPage-1?>&topup_page=<?=$topupPage?>">← Newer</a><?php endif;if($ledgerCount>$ledgerPage*50):?><a href="?ledger_page=<?=$ledgerPage+1?>&topup_page=<?=$topupPage?>">Earlier →</a><?php endif;?></nav></section><?php
}
