 $profile=customer_profile((int)$u['id']);$welcome=one("SELECT status,sent_at,last_error FROM email_queue WHERE event_key=? OR event_key LIKE ? ORDER BY id DESC LIMIT 1",['account:created:'.$u['id'],'account:welcome_resend:'.$u['id'].':%']);
