}
function customer_returns(array $u):void{
 ?><section class="c-panel"><span class="c-eyebrow">WE’RE HERE TO HELP</span><h2>Let’s put things right.</h2><p class="c-muted">Ask about an order, a change, cancellation, return or refund. Our team reviews each request; submitting a request does not automatically move money.</p><a href="/page/refunds" class="c-text-button">Read our refund policy ↗</a><details class="c-disclosure"><summary>＋ Start a request</summary><?php customer_form('request');?><label for="request-order">Order</label><select id="request-order" name="order_id"><option value="0">Account / general question</option><?php foreach(all('SELECT id,reference FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']]) as $order):?><option value="<?=$order['id']?>"><?=esc($order['reference'])?></option><?php endforeach;?></select><label for="request-kind">How can we help?</label><select id="request-kind" name="kind"><?php foreach(['help'=>'General help','change'=>'Change an order','cancel'=>'Cancellation','return'=>'Return / quality concern','refund'=>'Refund review'] as $value=>$label):?><option value="<?=$value?>"><?=$label?></option><?php endforeach;?></select><label for="request-subject">Subject</label><input id="request-subject" name="subject" maxlength="150" required><label for="request-message">Tell us what happened</label><textarea id="request-message" name="message" rows="4" minlength="10" maxlength="3000" required></textarea><button class="c-button gold">Send request</button></form></details></section>
 <section class="c-panel"><h2>Your requests</h2><?php $requests=all('SELECT * FROM customer_requests WHERE user_id=? ORDER BY id DESC LIMIT 30',[$u['id']]);foreach($requests as $request):?><article class="c-request"><div class="c-section-title"><strong>#<?=$request['id']?> · <?=esc($request['subject'])?></strong><?php customer_status($request['status']);?></div><p><?=nl2br(esc($request['message']))?></p><?php if($request['reply']):?><blockquote><small>From our team</small><p><?=nl2br(esc($request['reply']))?></p></blockquote><?php endif;?></article><?php endforeach;if(!$requests):?><p class="c-muted">Your support requests and replies will appear here.</p><?php endif;?></section><section class="c-panel"><h2>Refund activity</h2><?php $refunds=all("SELECT r.*,COALESCE(o.reference,b.reference) reference FROM refund_requests r JOIN payments p ON p.id=r.payment_id LEFT JOIN orders o ON p.entity_type='order' AND o.id=p.entity_id LEFT JOIN bookings b ON p.entity_type='booking' AND b.id=p.entity_id WHERE o.user_id=? OR b.user_id=? ORDER BY r.id DESC LIMIT 20",[$u['id'],$u['id']]);foreach($refunds as $refund):?><div class="c-line-item"><div><strong><?=esc($refund['reference'])?></strong><small><?=esc($refund['gateway_status']==='wallet_credited'?'Returned to wallet':$refund['status'])?></small></div><b><?=money($refund['amount'])?></b></div><?php endforeach;if(!$refunds):?><p class="c-muted">Reviewed refunds will appear here. Wallet payments are refunded to the same wallet.</p><?php endif;?></section><?php
}
?>
